React Hooks完全指南：从基础到高级技巧引言React Hooks是React 16.8版本引入的一项革命性特性，它允许我们在不编写类组件的情况下使用状态管理和生命周期方法。Hooks的出现极大地简化了React代码的编写，使组件逻辑更加清晰可复用。本文将从基础到高级，全面讲解React Hooks的使用方法和最佳实践。
1. Hooks基础1.1 什么是Hooks？Hooks是一些可以让你在函数组件中”钩入”React状态和生命周期特性的函数。React提供了一些内置Hooks，如useState、useEffect等，同时也允许你创建自定义Hooks。
1.2 为什么使用Hooks？
组件复用更简单：Hooks解决了类组件中逻辑复用的难题（如高阶组件和render props的复杂性）
代码更简洁：函数组件通常比类组件更简洁易读
关注点分离：Hooks允许你将相关逻辑组合在一起，而不是分散在不同的生命周期方法中
更容易理解：避免了this关键字带来的困惑

2. 常用基础Hooks2.1 useState：状态管理useState是最基本的Hooks，用于在函数组件中添加状态。
import React, &#123; useState &#125; from &#x27;react&#x27;;function Counter() &#123;  // 声明一个状态变量count，初始值为0  // setCount是更新count的函数  const [count, setCount] = useState(0);  return (    &lt;div&gt;      &lt;p&gt;你点击了 &#123;count&#125; 次&lt;/p&gt;      &lt;button onClick=&#123;() =&gt; setCount(count + 1)&#125;&gt;        点击我      &lt;/button&gt;    &lt;/div&gt;  );&#125;

2.2 useEffect：副作用管理useEffect用于处理组件的副作用，如数据获取、订阅、DOM操作等。它相当于类组件中的componentDidMount、componentDidUpdate和componentWillUnmount的组合。
import React, &#123; useState, useEffect &#125; from &#x27;react&#x27;;function Example() &#123;  const [count, setCount] = useState(0);  // 相当于componentDidMount和componentDidUpdate  useEffect(() =&gt; &#123;    // 更新文档标题    document.title = `你点击了 $&#123;count&#125; 次`;    // 清理函数，相当于componentWillUnmount    return () =&gt; &#123;      document.title = &#x27;React App&#x27;;    &#125;;  &#125;, [count]); // 只有当count改变时才会重新执行  return (    &lt;div&gt;      &lt;p&gt;你点击了 &#123;count&#125; 次&lt;/p&gt;      &lt;button onClick=&#123;() =&gt; setCount(count + 1)&#125;&gt;        点击我      &lt;/button&gt;    &lt;/div&gt;  );&#125;

2.3 useContext：上下文管理useContext用于在组件中访问React的上下文，避免了通过props层层传递数据。
import React, &#123; useContext &#125; from &#x27;react&#x27;;// 创建上下文const ThemeContext = React.createContext(&#x27;light&#x27;);function ThemedButton() &#123;  // 访问上下文  const theme = useContext(ThemeContext);  return (    &lt;button style=&#123;&#123; background: theme === &#x27;dark&#x27; ? &#x27;#333&#x27; : &#x27;#fff&#x27;, color: theme === &#x27;dark&#x27; ? &#x27;#fff&#x27; : &#x27;#333&#x27; &#125;&#125;&gt;      &#123;theme&#125; 主题按钮    &lt;/button&gt;  );&#125;// 在组件树的上层提供上下文值function App() &#123;  return (    &lt;ThemeContext.Provider value=&quot;dark&quot;&gt;      &lt;ThemedButton /&gt;    &lt;/ThemeContext.Provider&gt;  );&#125;

3. 高级Hooks3.1 useReducer：复杂状态管理useReducer是useState的替代方案，适用于复杂状态逻辑。
import React, &#123; useReducer &#125; from &#x27;react&#x27;;// 定义reducer函数function counterReducer(state, action) &#123;  switch (action.type) &#123;    case &#x27;increment&#x27;:      return &#123; count: state.count + 1 &#125;;    case &#x27;decrement&#x27;:      return &#123; count: state.count - 1 &#125;;    case &#x27;reset&#x27;:      return &#123; count: 0 &#125;;    default:      throw new Error();  &#125;&#125;function Counter() &#123;  // 初始化状态和dispatch函数  const [state, dispatch] = useReducer(counterReducer, &#123; count: 0 &#125;);  return (    &lt;div&gt;      &lt;p&gt;Count: &#123;state.count&#125;&lt;/p&gt;      &lt;button onClick=&#123;() =&gt; dispatch(&#123; type: &#x27;increment&#x27; &#125;)&#125;&gt;+&lt;/button&gt;      &lt;button onClick=&#123;() =&gt; dispatch(&#123; type: &#x27;decrement&#x27; &#125;)&#125;&gt;-&lt;/button&gt;      &lt;button onClick=&#123;() =&gt; dispatch(&#123; type: &#x27;reset&#x27; &#125;)&#125;&gt;Reset&lt;/button&gt;    &lt;/div&gt;  );&#125;

3.2 useCallback：记忆化回调函数useCallback用于记忆化回调函数，避免不必要的重新渲染。
import React, &#123; useState, useCallback &#125; from &#x27;react&#x27;;function Parent() &#123;  const [count, setCount] = useState(0);  // 只有当count改变时，才会创建新的回调函数  const increment = useCallback(() =&gt; &#123;    setCount(c =&gt; c + 1);  &#125;, [count]);  return (    &lt;div&gt;      &lt;Child onIncrement=&#123;increment&#125; /&gt;      &lt;button onClick=&#123;increment&#125;&gt;增加计数&lt;/button&gt;    &lt;/div&gt;  );&#125;function Child(&#123; onIncrement &#125;) &#123;  return &lt;button onClick=&#123;onIncrement&#125;&gt;子组件按钮&lt;/button&gt;;&#125;

3.3 useMemo：记忆化计算结果useMemo用于记忆化计算结果，避免在每次渲染时都重新计算。
import React, &#123; useState, useMemo &#125; from &#x27;react&#x27;;function ExpensiveCalculation(&#123; num &#125;) &#123;  // 只有当num改变时，才会重新计算  const result = useMemo(() =&gt; &#123;    console.log(&#x27;计算中...&#x27;);    // 模拟耗时计算    let sum = 0;    for (let i = 0; i &lt; num * 1000000; i++) &#123;      sum += i;    &#125;    return sum;  &#125;, [num]);  return &lt;div&gt;计算结果: &#123;result&#125;&lt;/div&gt;;&#125;

3.4 useRef：引用DOM元素或保存可变值useRef用于引用DOM元素或保存不需要引起重新渲染的可变值。
import React, &#123; useRef, useEffect &#125; from &#x27;react&#x27;;function TextInputWithFocusButton() &#123;  // 创建一个引用  const inputEl = useRef(null);  const onButtonClick = () =&gt; &#123;    // 聚焦输入框    inputEl.current.focus();  &#125;;  return (    &lt;div&gt;      &lt;input ref=&#123;inputEl&#125; type=&quot;text&quot; /&gt;      &lt;button onClick=&#123;onButtonClick&#125;&gt;聚焦输入框&lt;/button&gt;    &lt;/div&gt;  );&#125;

4. 自定义Hooks自定义Hooks允许你将组件逻辑提取到可复用的函数中。
4.1 示例：useFetchimport &#123; useState, useEffect &#125; from &#x27;react&#x27;;function useFetch(url) &#123;  const [data, setData] = useState(null);  const [loading, setLoading] = useState(true);  const [error, setError] = useState(null);  useEffect(() =&gt; &#123;    const fetchData = async () =&gt; &#123;      try &#123;        const response = await fetch(url);        const json = await response.json();        setData(json);      &#125; catch (err) &#123;        setError(err);      &#125; finally &#123;        setLoading(false);      &#125;    &#125;;    fetchData();    // 清理函数    return () =&gt; &#123;      // 取消请求的逻辑（如果需要）    &#125;;  &#125;, [url]);  return &#123; data, loading, error &#125;;&#125;// 使用自定义Hookfunction DataFetcher() &#123;  const &#123; data, loading, error &#125; = useFetch(&#x27;https://api.example.com/data&#x27;);  if (loading) return &lt;div&gt;加载中...&lt;/div&gt;;  if (error) return &lt;div&gt;出错了: &#123;error.message&#125;&lt;/div&gt;;  return (    &lt;div&gt;      &lt;h2&gt;获取的数据&lt;/h2&gt;      &lt;pre&gt;&#123;JSON.stringify(data, null, 2)&#125;&lt;/pre&gt;    &lt;/div&gt;  );&#125;

5. Hooks最佳实践5.1 只在顶层调用Hooks不要在循环、条件或嵌套函数中调用Hooks，确保每次渲染时Hooks的调用顺序一致。
5.2 只在函数组件中调用Hooks不要在普通JavaScript函数中调用Hooks（自定义Hooks除外）。
5.3 依赖数组要正确设置对于useEffect、useCallback、useMemo等，确保依赖数组包含了所有需要监听的变量。
5.4 避免不必要的依赖不要将对象或函数作为依赖项，除非它们确实会改变。可以使用useCallback或useMemo来记忆化这些值。
5.5 使用ESLint插件使用eslint-plugin-react-hooks插件来帮助你遵守Hooks的规则。
6. 常见陷阱和解决方案6.1 闭包陷阱// 问题代码function Counter() &#123;  const [count, setCount] = useState(0);  useEffect(() =&gt; &#123;    const interval = setInterval(() =&gt; &#123;      console.log(count); // 总是输出0      setCount(count + 1);    &#125;, 1000);    return () =&gt; clearInterval(interval);  &#125;, []); // 空依赖数组  return &lt;div&gt;&#123;count&#125;&lt;/div&gt;;&#125;

解决方案：
// 方案1：添加count到依赖数组useEffect(() =&gt; &#123;  const interval = setInterval(() =&gt; &#123;    setCount(count + 1);  &#125;, 1000);  return () =&gt; clearInterval(interval);&#125;, [count]);// 方案2：使用函数形式的setStateuseEffect(() =&gt; &#123;  const interval = setInterval(() =&gt; &#123;    setCount(prevCount =&gt; prevCount + 1);  &#125;, 1000);  return () =&gt; clearInterval(interval);&#125;, []);

6.2 无限循环当useEffect的依赖项在每次渲染时都发生变化时，可能会导致无限循环。
// 问题代码function App() &#123;  const [data, setData] = useState(&#123;&#125;);  useEffect(() =&gt; &#123;    // 异步获取数据    fetchData().then(result =&gt; setData(result));  &#125;, [data]); // data每次都是新对象，导致无限循环  return &lt;div&gt;&#123;JSON.stringify(data)&#125;&lt;/div&gt;;&#125;

解决方案：
// 方案1：指定具体的依赖项useEffect(() =&gt; &#123;  fetchData().then(result =&gt; setData(result));&#125;, [data.id]); // 只依赖data的id属性// 方案2：使用useCallback或useMemoconst fetchData = useCallback(async () =&gt; &#123;  // 获取数据的逻辑&#125;, []);useEffect(() =&gt; &#123;  fetchData().then(result =&gt; setData(result));&#125;, [fetchData]);

7. 总结React Hooks彻底改变了我们编写React组件的方式，使代码更加简洁、可复用和易于维护。通过掌握基础Hooks（如useState、useEffect）和高级Hooks（如useReducer、useCallback），以及遵循最佳实践，你可以编写出更高质量的React应用。
自定义Hooks是Hooks特性中最强大的部分之一，它允许你将组件逻辑提取到可复用的函数中，进一步提高代码的复用性和可维护性。
随着React的不断发展，Hooks已经成为React开发的主流方式，掌握Hooks对于现代React开发者来说至关重要。

Vue.js 3组合式API完全指南Vue.js 3引入的组合式API是一次重大革新，它提供了更灵活、更强大的方式来组织和复用组件逻辑。本文将深入探讨组合式API的核心概念、使用方法和最佳实践。
一、组合式API简介1.1 为什么引入组合式API?Vue.js 2的选项式API(Options API)在中小型应用中表现良好，但在大型复杂组件中存在以下问题：

代码组织分散，相关逻辑分布在不同选项中
难以提取和复用组件逻辑
类型推断支持有限

组合式API通过以下方式解决这些问题：

将相关逻辑聚合在一个函数中
提供更灵活的代码组织方式
更好的TypeScript支持
更易于测试和维护

1.2 组合式API与选项式API的对比// 选项式APIexport default &#123;  data() &#123;    return &#123;      count: 0    &#125;  &#125;,  methods: &#123;    increment() &#123;      this.count++    &#125;  &#125;,  computed: &#123;    doubleCount() &#123;      return this.count * 2    &#125;  &#125;&#125;// 组合式APIimport &#123; ref, computed &#125; from &#x27;vue&#x27;export default &#123;  setup() &#123;    const count = ref(0)    const increment = () =&gt; &#123; count.value++ &#125;    const doubleCount = computed(() =&gt; count.value * 2)    return &#123;      count,      increment,      doubleCount    &#125;  &#125;&#125;

二、组合式API核心概念2.1 响应式系统组合式API的响应式系统基于ref和reactive：
import &#123; ref, reactive, toRefs &#125; from &#x27;vue&#x27;// 基本类型响应式const count = ref(0)console.log(count.value) // 0count.value++ // 修改值// 对象类型响应式const user = reactive(&#123;  name: &#x27;John&#x27;,  age: 30&#125;)console.log(user.name) // Johnuser.age = 31 // 修改值// 将reactive对象转换为refconst &#123; name, age &#125; = toRefs(user)

2.2 生命周期钩子组合式API提供了与选项式API对应的生命周期钩子：
import &#123; onMounted, onUpdated, onUnmounted &#125; from &#x27;vue&#x27;export default &#123;  setup() &#123;    onMounted(() =&gt; &#123;      console.log(&#x27;组件挂载完成&#x27;)    &#125;)    onUpdated(() =&gt; &#123;      console.log(&#x27;组件更新完成&#x27;)    &#125;)    onUnmounted(() =&gt; &#123;      console.log(&#x27;组件卸载完成&#x27;)    &#125;)  &#125;&#125;

2.3 计算属性与监听器import &#123; ref, computed, watch &#125; from &#x27;vue&#x27;export default &#123;  setup() &#123;    const count = ref(0)    // 计算属性    const doubleCount = computed(() =&gt; count.value * 2)    // 监听器    watch(count, (newValue, oldValue) =&gt; &#123;      console.log(`count从$&#123;oldValue&#125;变为$&#123;newValue&#125;`)    &#125;)    // 监听多个源    watch([count, doubleCount], ([newCount, newDoubleCount], [oldCount, oldDoubleCount]) =&gt; &#123;      console.log(`count: $&#123;oldCount&#125; -&gt; $&#123;newCount&#125;`)      console.log(`doubleCount: $&#123;oldDoubleCount&#125; -&gt; $&#123;newDoubleCount&#125;`)    &#125;)    // 立即执行的监听器    watch(count, (newValue) =&gt; &#123;      console.log(`当前count值: $&#123;newValue&#125;`)    &#125;, &#123;      immediate: true    &#125;)    return &#123;      count,      doubleCount    &#125;  &#125;&#125;

三、组合式API高级特性3.1 自定义组合函数自定义组合函数是组合式API中代码复用的核心机制：
// useCounter.jsimport &#123; ref, computed &#125; from &#x27;vue&#x27;export function useCounter(initialValue = 0) &#123;  const count = ref(initialValue)  const increment = () =&gt; &#123; count.value++ &#125;  const decrement = () =&gt; &#123; count.value-- &#125;  const doubleCount = computed(() =&gt; count.value * 2)  return &#123;    count,    increment,    decrement,    doubleCount  &#125;&#125;// 在组件中使用import &#123; useCounter &#125; from &#x27;./useCounter&#x27;export default &#123;  setup() &#123;    const &#123; count, increment, decrement, doubleCount &#125; = useCounter(10)    return &#123;      count,      increment,      decrement,      doubleCount    &#125;  &#125;&#125;

3.2 依赖注入组合式API提供了provide和inject来实现组件间通信：
// 父组件import &#123; provide, ref &#125; from &#x27;vue&#x27;export default &#123;  setup() &#123;    const theme = ref(&#x27;light&#x27;)    provide(&#x27;theme&#x27;, theme)    const toggleTheme = () =&gt; &#123;      theme.value = theme.value === &#x27;light&#x27; ? &#x27;dark&#x27; : &#x27;light&#x27;    &#125;    return &#123;      toggleTheme    &#125;  &#125;&#125;// 子组件import &#123; inject &#125; from &#x27;vue&#x27;export default &#123;  setup() &#123;    const theme = inject(&#x27;theme&#x27;)    return &#123;      theme    &#125;  &#125;&#125;

3.3 模板引用使用ref可以访问DOM元素或组件实例：
import &#123; ref, onMounted &#125; from &#x27;vue&#x27;export default &#123;  setup() &#123;    const inputRef = ref(null)    onMounted(() =&gt; &#123;      inputRef.value.focus() // 聚焦输入框    &#125;)    return &#123;      inputRef    &#125;  &#125;&#125;

在模板中：
&lt;input ref=&quot;inputRef&quot; /&gt;

四、组合式API实战技巧4.1 代码组织
将相关逻辑放在同一组合函数中
按功能划分组合函数
使用自定义组合函数封装第三方库

// useAxios.jsimport &#123; ref, onUnmounted &#125; from &#x27;vue&#x27;import axios from &#x27;axios&#x27;export function useAxios(url) &#123;  const data = ref(null)  const loading = ref(false)  const error = ref(null)  const controller = new AbortController()  const fetchData = async () =&gt; &#123;    loading.value = true    error.value = null    try &#123;      const response = await axios.get(url, &#123;        signal: controller.signal      &#125;)      data.value = response.data    &#125; catch (err) &#123;      if (err.name !== &#x27;AbortError&#x27;) &#123;        error.value = err.message      &#125;    &#125; finally &#123;      loading.value = false    &#125;  &#125;  fetchData()  onUnmounted(() =&gt; &#123;    controller.abort() // 组件卸载时取消请求  &#125;)  return &#123;    data,    loading,    error,    refetch: fetchData  &#125;&#125;

4.2 组件通信
父子组件：props和emit
跨层级组件：provide和inject
兄弟组件：事件总线或状态管理

// 子组件import &#123; defineProps, defineEmits &#125; from &#x27;vue&#x27;export default &#123;  props: defineProps(&#123;    message: String  &#125;),  emits: defineEmits([&#x27;update:message&#x27;]),  setup(props, &#123; emit &#125;) &#123;    const updateMessage = (newMessage) =&gt; &#123;      emit(&#x27;update:message&#x27;, newMessage)    &#125;    return &#123;      updateMessage    &#125;  &#125;&#125;

4.3 状态管理对于复杂应用，可使用Pinia(Vue官方推荐的状态管理库)：
// store/counter.jsimport &#123; defineStore &#125; from &#x27;pinia&#x27;export const useCounterStore = defineStore(&#x27;counter&#x27;, &#123;  state: () =&gt; (&#123;    count: 0  &#125;),  getters: &#123;    doubleCount: (state) =&gt; state.count * 2  &#125;,  actions: &#123;    increment() &#123;      this.count++    &#125;,    decrement() &#123;      this.count--    &#125;  &#125;&#125;)// 在组件中使用import &#123; useCounterStore &#125; from &#x27;@/store/counter&#x27;export default &#123;  setup() &#123;    const counterStore = useCounterStore()    return &#123;      counterStore    &#125;  &#125;&#125;

五、Vue.js 3新特性5.1 TeleportTeleport允许将组件内容渲染到DOM中的任意位置：
